var mySize;
var colors1 = ["#1fc89c", "#f9858f", "#Ca28e01", "#24d6f5", "#dc571b", "#9ccf56"];
var colors2 = ["#1e5348", "#825747", ];
let seed = Math.random()*1000;

function setup() {
	randomSeed(seed);
	//frameRate(1);
	mySize = max(windowWidth, windowHeight);
	createCanvas(windowWidth, windowHeight);
	//colorMode(HSB, 360, 100, 100, 100);
	background(10);
}

function draw() {
	randomSeed(seed);
	background(10);

	for (let i = 0; i < mySize / 15; i++) {
		// position
		let x = randomGaussian(0.5, 0.3) * width;
		let y = randomGaussian(0.5, 0.3) * height;

		// size of shapes
		let d = random(20) + 80;
		let l = random(10, mySize / 2) * random();

		// angle
		let ang = int(random(6, 12)) * (TAU / 4);

		push();
		translate(x, y);
		rotate(ang);

		noFill();
		strokeCap(SQUARE);
		//stroke(100, 40, 75, random(95, 55));
		manyCircle(0, 0, d);
		pop();
	}
}

function manyCircle(x, y, d) {
	let num = int(random(2, 20));
	for (let i = 0; i < num; i++) {
		circ(x, y, d * random());
	}
}

function circ(x, y, d) {
	let options2 = int(random(2));

	push();
	translate(x, y);
	rotate(PI * 0.25 * random(1));
	strokeWeight(random(0.25, 0.75));

	if (options2 == 0) {
		var num = int(random(3, 9));
		var l = d * random(0.1, 0.6);
		for (let a = 0; a < TAU; a += TAU / num) {
			stroke(random(colors2));
			line(d * 0.75 * cos(a), d * 0.75 * sin(a), l * cos(a), l * sin(a));
		}
	} else if (options2 == 1) {
		var num = int(random(4, 20));
		strokeWeight(random(0.25, 12));
		stroke(random(colors1));
		//stroke(random(360), 90, 75, random(95, 55));
		for (let a = 0; a < TAU; a += TAU / num) {
			point(d * 0.75 * cos(a), d * 0.75 * sin(a));
		}
	} else {
		stroke(random(colors1));
		circle(0, 0, d / 10.25);
	}
	pop();
}

function mouseClicked() {
	seed = Math.random()*1000;
	randomSeed(seed);
	background(10);
	loop();

}

function keyTyped() {
	if (key === "s" || key === "S") {
		noLoop();
		saveCanvas("ColorfulFireworks-001", "png");
	}
}

